#!/usr/bin/env node
// Generate `crates/wordless-builder/src/palette_data.rs` from the admin
// element/icon libraries — the builder palette IS the library, not a
// copy, so the icon list (104) and element export list (26) are derived
// from the TS sources, never hand-typed.
//
//   node scripts/gen-builder-palette.mjs
//
// The check script (`scripts/check-builder-palette.mjs`) fails when
// this generated file drifts from the TS sources.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const ROOT = path.resolve(__dirname, "..");
const ICONS_TS = path.join(ROOT, "admin/src/components/icons.tsx");
const ELEMENTS_TS = path.join(ROOT, "admin/src/components/elements.tsx");
const OUT = path.join(ROOT, "crates/wordless-builder/src/palette_data.rs");

const iconsSrc = fs.readFileSync(ICONS_TS, "utf8");
const elementsSrc = fs.readFileSync(ELEMENTS_TS, "utf8");

// IconName union: `export type IconName =\n  | "home"\n ... ;`
const union = iconsSrc.match(/export type IconName =([\s\S]*?);/);
if (!union) throw new Error("IconName union not found in icons.tsx");
const names = [...union[1].matchAll(/"([^"]+)"/g)].map((m) => m[1]);

// Group comments inside the PATHS record, in order:
//   // Content & editing\n  home: (...
// The last comment's text is long ("Kept from v1 (still referenced
// by existing pages, not in the preview 72)") — shorten it to its
// first clause for the palette group label.
const groups = [];
const pathsSection = iconsSrc.slice(iconsSrc.indexOf("const PATHS"));
const groupRe = /\/\/ ([^\n]+)\n\s*([A-Za-z]+):/g;
let gm;
while ((gm = groupRe.exec(pathsSection)) !== null) {
  let label = gm[1].trim();
  if (label.startsWith("Kept from v1")) label = "Kept from v1";
  groups.push({ group: label, first: gm[2] });
}
// Assign each icon the group of the last comment at or before it.
// The PATHS keys are in the same order as the union.
const pathsKeys = [...pathsSection.matchAll(/^\s{2}([A-Za-z]+):/gm)].map((m) => m[1]);
const iconGroup = new Map();
let gi = 0;
for (const key of pathsKeys) {
  while (gi + 1 < groups.length && groups[gi + 1].first === key) gi++;
  // The group whose `first` key is this key (or an earlier one).
  let g = groups[0].group;
  for (let i = 0; i < groups.length; i++) {
    if (pathsKeys.indexOf(groups[i].first) <= pathsKeys.indexOf(key)) g = groups[i].group;
  }
  iconGroup.set(key, g);
}
const icons = names.map((n) => [n, iconGroup.get(n) || "System & tools"]);
const missing = names.filter((n) => !pathsKeys.includes(n));
if (missing.length) throw new Error(`icons without a PATHS entry: ${missing.join(", ")}`);

// Element exports: `export function Name(` in elements.tsx.
const exportsList = [...elementsSrc.matchAll(/^export function (\w+)/gm)].map((m) => m[1]);

const rustStr = (s) => `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
const lines = [];
lines.push("//! Generated by `scripts/gen-builder-palette.mjs` from the admin");
lines.push("//! element/icon libraries (`admin/src/components/icons.tsx` and");
lines.push("//! `admin/src/components/elements.tsx`). Do NOT edit by hand —");
lines.push("//! re-run the generator. `scripts/check-builder-palette.mjs`");
lines.push("//! fails when this file drifts from the TS sources.");
lines.push("");
lines.push("/// (icon name, group) — every icon in the admin icon library,");
lines.push("/// in the order of the `IconName` union in `icons.tsx`.");
lines.push(`pub const BUILDER_ICONS: &[(&str, &str)] = &[`);
for (const [name, group] of icons) lines.push(`    (${rustStr(name)}, ${rustStr(group)}),`);
lines.push("];");
lines.push("");
lines.push("/// Every component export in `admin/src/components/elements.tsx`.");
lines.push(`pub const ELEMENT_EXPORTS: &[&str] = &[`);
for (const e of exportsList) lines.push(`    ${rustStr(e)},`);
lines.push("];");
lines.push("");
fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, lines.join("\n"));
console.log(`wrote ${OUT}: ${icons.length} icons, ${exportsList.length} element exports`);
